const fs=require('fs');
const path=require('path');
const BASE='/pdfs';
const STATE='/home/node/.n8n/estado/procesados.json';
let done=new Set();
try{done=new Set(JSON.parse(fs.readFileSync(STATE,'utf8')));}catch(e){}
const out=[];
function walk(dir){for(const entry of fs.readdirSync(dir,{withFileTypes:true})){const full=path.join(dir,entry.name);if(entry.isDirectory()){const n=entry.name.toLowerCase();if(n==='procesados'||n==='errores')continue;walk(full);}else if(entry.name.toLowerCase().endsWith('.pdf')){const cat=path.basename(path.dirname(full));const key=cat+'/'+entry.name;if(done.has(key))continue;out.push({json:{fileName:entry.name,categoria:cat,filePath:full},binary:{data:{data:fs.readFileSync(full).toString('base64'),mimeType:'application/pdf',fileName:entry.name}}});}}}
walk(BASE);
return out;

