const fs=require('fs');
const path=require('path');
const FILE='/home/node/.n8n/estado/procesados.json';
const items=$input.all();
let done=[];
try{done=JSON.parse(fs.readFileSync(FILE,'utf8'));}catch(e){}
const nuevos=items.map(i=>{const j=i.json;const ok=j['Estado Documento']!=='Error';const key=(j['_carpeta']||'')+'/'+(j['_archivo']||'');return ok&&key.length>2?key:null;}).filter(Boolean);
done=Array.from(new Set(done.concat(nuevos)));
fs.mkdirSync(path.dirname(FILE),{recursive:true});
fs.writeFileSync(FILE,JSON.stringify(done,null,2));
for(const item of items){const j=item.json;const cat=j['_carpeta']||'';const name=j['_archivo']||'';if(cat==='N/A'||name==='N/A'||!cat||!name)continue;const src=path.join('/pdfs',cat,name);const sub=j['Estado Documento']==='Error'?'Errores':'Procesados';const dest=path.join('/pdfs',sub,cat,name);try{fs.mkdirSync(path.dirname(dest),{recursive:true});fs.renameSync(src,dest);}catch(e){}}
